use vstd::prelude::*;

verus! {
    #[verifier(custom_adt)]
    pub enum OpType {
        Add,
        Multiply,
        LogicalAnd,
        LogicalOr,
    }

    // Mathematical semantics of the four operations on unbounded integers.
    spec fn op_sem(op: OpType, x: int, y: int) -> int {
        match op {
            OpType::Add => x + y,
            OpType::Multiply => x * y,
            OpType::LogicalAnd => if x != 0 && y != 0 { 1 } else { 0 },
            OpType::LogicalOr  => if x != 0 || y != 0 { 1 } else { 0 },
        }
    }

    // Given an operation selector, returns Some(id) if id is an identity element
    // for that operation, or None if no identity exists.
    fn ufunc_identity(op: OpType) -> (result: Option<i8>)
        ensures
            match result {
                Option::Some(id) => 
                    // id really is a two‐sided identity
                    forall |x: i8|
                        op_sem(op, x as int, id as int) == x as int &&
                        op_sem(op, id as int, x as int) == x as int,
                Option::None =>
                    // for every candidate id, there is some x that falsifies identity
                    forall |id: i8|
                        exists |x: i8|
                            op_sem(op, x as int, id as int) != x as int ||
                            op_sem(op, id as int, x as int) != x as int,
            }
    {
        match op {
            OpType::Add => {
                // 0 + x = x  and  x + 0 = x
                assert(forall |x: i8|
                    op_sem(OpType::Add, x as int, 0) == x as int &&
                    op_sem(OpType::Add, 0, x as int) == x as int
                ) by {
                    intro x;
                    assert(x as int + 0 == x as int);
                    assert(0 + x as int == x as int);
                };
                result = Some(0);
            }
            OpType::Multiply => {
                // 1 * x = x  and  x * 1 = x
                assert(forall |x: i8|
                    op_sem(OpType::Multiply, x as int, 1) == x as int &&
                    op_sem(OpType::Multiply, 1, x as int) == x as int
                ) by {
                    intro x;
                    assert(x as int * 1 == x as int);
                    assert(1 * x as int == x as int);
                };
                result = Some(1);
            }
            OpType::LogicalAnd => {
                // No identity: witness x = 2 always fails for op(x, id) = x
                assert(forall |id: i8|
                    exists |x: i8|
                        op_sem(OpType::LogicalAnd, x as int, id as int) != x as int ||
                        op_sem(OpType::LogicalAnd, id as int, x as int) != x as int
                ) by {
                    intro id;
                    // pick x = 2 (nonzero)
                    exists(2);
                    // then op_sem(2, id) ∈ {0,1}, never 2
                    assert(op_sem(OpType::LogicalAnd, 2, id as int) != 2);
                    assert(
                        op_sem(OpType::LogicalAnd, 2, id as int) != 2 ||
                        op_sem(OpType::LogicalAnd, id as int, 2) != 2
                    );
                };
                result = None;
            }
            OpType::LogicalOr => {
                // No identity: witness x = 2 always fails for op(x, id) = x
                assert(forall |id: i8|
                    exists |x: i8|
                        op_sem(OpType::LogicalOr, x as int, id as int) != x as int ||
                        op_sem(OpType::LogicalOr, id as int, x as int) != x as int
                ) by {
                    intro id;
                    exists(2);
                    assert(op_sem(OpType::LogicalOr, 2, id as int) != 2);
                    assert(
                        op_sem(OpType::LogicalOr, 2, id as int) != 2 ||
                        op_sem(OpType::LogicalOr, id as int, 2) != 2
                    );
                };
                result = None;
            }
        }
        result
    }

    fn main() {}
}